package juloo.keyboard2.suggestions;

import java.io.ByteArrayOutputStream;
import java.io.DataOutputStream;
import java.nio.charset.StandardCharsets;
import org.junit.Test;
import static org.junit.Assert.*;

public class BigramsTest
{
  public BigramsTest() {}

  // Sorted by UTF-8 bytes, like the files generated by 'gen_bigrams.py'.
  static final String[] WORDS = { "acció", "es", "seu", "seva", "és" };
  static final int ACCIO = 0, ES = 1, SEU = 2, SEVA = 3, ES_ACCENT = 4;
  static final int BACKOFF = 5;

  /** A file in which "és" follows "acció" and nothing follows other
      words. */
  static Bigrams sample() throws Exception
  {
    ByteArrayOutputStream bytes = new ByteArrayOutputStream();
    DataOutputStream out = new DataOutputStream(bytes);
    out.writeBytes("UKBG");
    out.writeByte(1);
    out.writeInt(WORDS.length);
    out.writeByte(BACKOFF);
    int off = 0;
    out.writeInt(0);
    for (String w : WORDS)
    {
      off += w.getBytes(StandardCharsets.UTF_8).length;
      out.writeInt(off);
    }
    for (String w : WORDS)
      out.write(w.getBytes(StandardCharsets.UTF_8));
    for (int i = 0; i < WORDS.length; i++)
      out.writeByte(40 + i); // Unigram costs
    // Entry offsets: only "acció", the first word, has entries.
    out.writeInt(0);
    for (int i = 0; i < WORDS.length; i++)
      out.writeInt(2);
    out.writeInt((ES << 8) | 30);
    out.writeInt((ES_ACCENT << 8) | 10);
    return Bigrams.of_bytes(bytes.toByteArray());
  }

  @Test
  public void find() throws Exception
  {
    Bigrams bg = sample();
    assertEquals(WORDS.length, bg.length());
    for (int i = 0; i < WORDS.length; i++)
    {
      assertEquals(i, bg.find(WORDS[i]));
      assertEquals(WORDS[i], bg.word(i));
    }
    assertEquals(-1, bg.find("e"));
    assertEquals(-1, bg.find("zz"));
    assertEquals(-1, bg.find(""));
  }

  @Test
  public void cost() throws Exception
  {
    Bigrams bg = sample();
    assertEquals(10, bg.cost(ACCIO, ES_ACCENT));
    assertEquals(30, bg.cost(ACCIO, ES));
    // Not listed: unigram cost and backoff.
    assertEquals(40 + SEU + BACKOFF, bg.cost(ACCIO, SEU));
    assertEquals(40 + ES + BACKOFF, bg.cost(SEVA, ES));
    assertEquals(40 + ES + BACKOFF, bg.cost(-1, ES));
    assertEquals(Bigrams.MAX_COST, bg.cost(ACCIO, -1));
  }

  @Test
  public void context() throws Exception
  {
    Bigrams bg = sample();
    assertEquals(ACCIO, Suggestions.context_index(bg, "acció"));
    assertEquals(ACCIO, Suggestions.context_index(bg, "Acció"));
    assertEquals(ACCIO, Suggestions.context_index(bg, "l'acció"));
    // Words without entries are not useful as context.
    assertEquals(-1, Suggestions.context_index(bg, "seva"));
    assertEquals(-1, Suggestions.context_index(bg, "unknown"));
    assertEquals(-1, Suggestions.context_index(bg, null));
  }

  @Test
  public void invalid()
  {
    try
    {
      Bigrams.of_bytes(new byte[]{ 'U', 'K', 'B', 'G', 1, 0, 0, 0, 0, 0 });
      fail("Truncated file accepted");
    }
    catch (Exception e) {}
    try
    {
      Bigrams.of_bytes("not a bigrams file".getBytes());
      fail("Invalid file accepted");
    }
    catch (Exception e) {}
  }
}
